-- Task cards (catalog list summary). Full bodies arrive in Phase 2.
-- Source: tasks-mockup/assets/js/data-tasks-*.js (generated, do not edit by hand).

CREATE TABLE IF NOT EXISTS tasks (
  id          TEXT PRIMARY KEY,
  title       TEXT NOT NULL,
  level_id    TEXT NOT NULL REFERENCES levels (id),
  tags        TEXT[] NOT NULL DEFAULT '{}',
  status      TEXT NOT NULL DEFAULT 'published',
  time_min    INTEGER NOT NULL DEFAULT 30,
  solved_rate INTEGER NOT NULL DEFAULT 0,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

